/**
 * ID generation. The REAL production IDs are generated by the backend.
 * These helpers exist so the mock services can produce realistic-looking
 * identifiers during the frontend phase.
 *
 * IMPORTANT: None of these IDs are ever used as security tokens.
 * Ticket QR payloads use opaque tokens generated by ticketTokens.js
 * (see below), and those are mocked placeholder strings — the real
 * backend will replace them with cryptographically signed tokens.
 */

const ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // no ambiguous chars
const HEX = "0123456789abcdef";

export function randomString(length = 10, alphabet = ALPHABET) {
  let out = "";
  const cryptoObj = globalThis.crypto;
  if (cryptoObj?.getRandomValues) {
    const buf = new Uint8Array(length);
    cryptoObj.getRandomValues(buf);
    for (let i = 0; i < length; i++) {
      out += alphabet[buf[i] % alphabet.length];
    }
    return out;
  }
  // Fallback for exotic environments (still fine for mock IDs).
  for (let i = 0; i < length; i++) {
    out += alphabet[Math.floor(Math.random() * alphabet.length)];
  }
  return out;
}

export const uid = (prefix = "id") => `${prefix}_${randomString(14)}`;
export const orderRef = () => `ORD-${randomString(8)}`;
export const ticketRef = () => `TKT-${randomString(8)}`;
export const paymentRef = () => `PAY-${randomString(10)}`;
export const eventRef = () => `EVT-${randomString(8)}`;
export const txRef = () => `TX-${randomString(10)}`;

/**
 * Opaque, non-guessable-looking token used as the QR payload in mock
 * mode. In production this MUST be a backend-signed token.
 */
export const ticketVerificationToken = () => randomString(48, `${HEX}${ALPHABET}`);

/** Local-only persistence key generator (never used for auth). */
export const storageKey = (namespace, key) => `th:${namespace}:${key}`;